# Token Interface
class Token:
    def __init__(self, address, chain_id, decimals, symbol=None, name=None, abi=None):
        self.address = address
        self.chain_id = chain_id
        self.decimals = decimals
        self.symbol = symbol
        self.name = name
        self.abi = abi

